add_filter( 'wc_order_statuses', 'perfectpixel_rename_completed_status' );
add_filter( 'woocommerce_register_shop_order_post_statuses', 'perfectpixel_rename_completed_status_count' );

function perfectpixel_rename_completed_status( $statuses ) {
	if ( isset( $statuses['wc-completed'] ) ) {
		$statuses['wc-completed'] = '{{completed_status_label}}';
	}
	return $statuses;
}

function perfectpixel_rename_completed_status_count( $statuses ) {
	if ( isset( $statuses['wc-completed'] ) ) {
		$statuses['wc-completed']['label'] = '{{completed_status_label}}';
		/* translators: %s: number of orders */
		$statuses['wc-completed']['label_count'] = _n_noop( '{{completed_status_label}} <span class="count">(%s)</span>', '{{completed_status_label}} <span class="count">(%s)</span>' );
	}
	return $statuses;
}
